def butterfly_pattern(n):
    total_rows = 2 * n - 1
    for r in range(1, total_rows + 1):          # r counts every row, top tip to bottom tip
        m = min(r, 2 * n - r)                     # this row's distance from the nearest tip
        for j in range(2 * n):                      # every row uses the same total width, 2n
            if j < m:
                print("*", end="")                     # inside the left wing
            elif j >= 2 * n - m:
                print("*", end="")                     # inside the right wing
            else:
                print(" ", end="")                     # the gap between the two wings
        print()                                    # move to the next line after the row


if __name__ == "__main__":
    butterfly_pattern(4)

